import sys
import unicodedata
from collections import Counter

def normalize(s):
    return ''.join(
        c for c in unicodedata.normalize('NFD', s)
        if unicodedata.category(c) != 'Mn'
    )

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return

    p = normalize(lines[0].strip())
    a = normalize(lines[1].strip())

    count_p = Counter(p)
    count_a = Counter(c for c in a if c != '*')

    for c, cnt in count_a.items():
        if count_p.get(c, 0) < cnt:
            print('N')
            return

    print('S')

if __name__ == '__main__':
